
`timescale 1ns/1ps
module tb_width_4to16;
    reg [3:0] in_val;
    wire [15:0] Y_sized;

    // Sized expression (as generated by compiler)
    assign Y_sized  = 16'b1 << in_val;

    integer err_sized = 0;
    integer tested_count = 0;

    initial begin
        
        in_val = 4'd0;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[0] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 0, Y_sized[0]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (0 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 0);
        end
        tested_count = tested_count + 1;

        in_val = 4'd1;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[1] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 1, Y_sized[1]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (1 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 1);
        end
        tested_count = tested_count + 1;

        in_val = 4'd2;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[2] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 2, Y_sized[2]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (2 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 2);
        end
        tested_count = tested_count + 1;

        in_val = 4'd7;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[7] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 7, Y_sized[7]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (7 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 7);
        end
        tested_count = tested_count + 1;

        in_val = 4'd14;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[14] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 14, Y_sized[14]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (14 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 14);
        end
        tested_count = tested_count + 1;

        in_val = 4'd15;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[15] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 15, Y_sized[15]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (15 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 15);
        end
        tested_count = tested_count + 1;

        $display("SUMMARY_4to16: tested=%0d err_sized=%0d", tested_count, err_sized);
        $finish;
    end
endmodule
